<script setup>
import { computed, ref } from 'vue'
import api from '@/api/axios'

const file=ref(null),importId=ref(''),preview=ref(null),busy=ref(false),stage=ref('ready'),message=ref(''),result=ref(null)
const invalidRows=computed(()=>preview.value?.rows?.filter(row=>row.status==='Invalid')||[])
const hasBlockingErrors=computed(()=>invalidRows.value.length>0||(preview.value?.workbookErrors?.length||0)>0)
const addedProducts=computed(()=>result.value?.results?.filter(row=>row.status==='Imported')||[])
const failedProducts=computed(()=>result.value?.results?.filter(row=>row.status!=='Imported')||[])
function chooseFile(event){file.value=event.target.files?.[0]||null;preview.value=null;result.value=null;importId.value='';message.value=''}
function saveBlob(blob,name){const url=URL.createObjectURL(blob);const anchor=document.createElement('a');anchor.href=url;anchor.download=name;anchor.click();URL.revokeObjectURL(url)}
async function downloadTemplate(){busy.value=true;try{const response=await api.get('/product-import/template',{responseType:'blob'});saveBlob(response.data,'south-west-product-import-template.xlsx')}catch(error){message.value=error.response?.data?.message||'Could not download the template.'}finally{busy.value=false}}
async function upload(){if(!file.value)return;busy.value=true;stage.value='validating';message.value='Checking the workbook…';const body=new FormData();body.append('file',file.value);try{const response=await api.post('/product-import/validate',body,{headers:{'Content-Type':'multipart/form-data'}});preview.value=response.data;importId.value=response.data.importId;stage.value='preview';message.value='Workbook checked. Review the results below.'}catch(error){message.value=error.response?.data?.message||'Could not check the workbook.';stage.value='ready'}finally{busy.value=false}}
async function downloadErrors(){try{const response=await api.get(`/product-import/${importId.value}/errors`,{responseType:'blob'});saveBlob(response.data,'product-import-errors.xlsx')}catch(error){message.value=error.response?.data?.message||'Could not download the error report.'}}
async function confirmImport(){if(!window.confirm(`Import all ${preview.value.counts.products} products and their variants?`))return;busy.value=true;stage.value='importing';message.value='Importing products and variants…';try{const response=await api.post(`/product-import/${importId.value}/confirm`,{confirm:true});result.value=response.data;stage.value='complete';message.value='Import processing complete.'}catch(error){message.value=error.response?.data?.message||'Import failed.';stage.value='preview'}finally{busy.value=false}}
async function retryFailed(){busy.value=true;stage.value='importing';message.value='Retrying products that failed to save…';try{const response=await api.post(`/product-import/${importId.value}/confirm`,{confirm:true,retry:true});result.value=response.data;stage.value='complete';message.value='Retry processing complete.'}catch(error){message.value=error.response?.data?.message||'Retry failed.';stage.value='complete'}finally{busy.value=false}}
</script>

<template>
  <main class="page-container import-page">
    <header class="page-header"><div><h1>Bulk Product Import</h1><p>Add products and their variants from one Excel workbook. Product codes and variant SKUs are created automatically.</p></div></header>
    <ol class="steps"><li>Get the template</li><li>Fill Products</li><li>Add Variants</li><li :class="{current:['validating','preview'].includes(stage)}">Upload and review</li><li :class="{current:['importing','complete'].includes(stage)}">Confirm and finish</li><li>Add specifications in admin</li></ol>
    <div v-if="message" class="notice" role="status">{{message}}</div>
    <section class="card"><div class="section-number">1</div><div class="section-body"><h2>Download the Excel template</h2><p>It includes separate sheets for Products and Variants. Reference Lists shows current categories, brands, item types, units, warranties, conditions, and stock locations.</p><button class="primary-button" type="button" :disabled="busy" @click="downloadTemplate">Download Excel template</button></div></section>
    <section class="card"><div class="section-number">2</div><div class="section-body"><h2>Fill in the workbook</h2><ul class="plain-list"><li>Add each product once on <strong>Products</strong>. Choose Unit of Measure, Warranty, and Condition from the lists, and enter Shipping Weight in kilograms.</li><li>Add at least one row for each product on <strong>Variants</strong>. Enter a selling price and all four checkout prices for each variant. QuickBooks Item Code is optional text for that variant.</li><li>Enter a non-negative Reorder Quantity for each variant. It accepts zero and up to three decimal places. Enter Stock Quantity separately for opening stock.</li><li>Choose an active Stock Location when Stock Quantity or Reorder Quantity is greater than zero. The preview shows the location and reorder quantity for each variant.</li><li>Mark one variant as the default, or leave all as No to use the first variant.</li><li>After the import, open <strong>Products &gt; Variants</strong>, edit each variant, and add its configured specifications there.</li></ul></div></section>
    <section class="card"><div class="section-number">3</div><div class="section-body"><h2>Upload and check the workbook</h2><p>Choose your completed .xlsx file (up to 10 MB). Everything is checked before products are added.</p><div class="upload-row"><input type="file" accept=".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" @change="chooseFile"><button class="primary-button" :disabled="!file||busy" @click="upload">{{busy&&stage==='validating'?'Checking workbook…':'Upload and check'}}</button></div><progress v-if="busy" max="100" :value="stage==='validating'?55:stage==='importing'?80:100" aria-label="Processing progress"></progress></div></section>
    <template v-if="preview">
      <section class="card review-card"><div class="section-number">4</div><div class="section-body"><div class="card-heading"><div><h2>Review the check results</h2><p>Fix all issues in the workbook, then upload it again. Products cannot be imported while errors remain.</p></div><button v-if="hasBlockingErrors" class="secondary-button" @click="downloadErrors">Download error report</button></div>
        <div class="stats"><div><b>{{preview.counts.products}}</b><span>Products</span></div><div><b>{{preview.counts.variants}}</b><span>Variants</span></div><div><b>{{preview.counts.valid}}</b><span>Ready</span></div><div><b>{{preview.counts.invalid+(preview.workbookErrors?.length?1:0)}}</b><span>Needs attention</span></div></div>
        <div class="table-wrap"><table><thead><tr><th>Worksheet</th><th>Excel row</th><th>Column</th><th>What needs fixing</th><th>Suggested correction</th></tr></thead><tbody><tr v-for="issue in preview.workbookErrors" :key="`${issue.sheet}-${issue.rowNumber}-${issue.column}-${issue.error}`"><td>{{issue.sheet}}</td><td>{{issue.rowNumber}}</td><td>{{issue.column}}</td><td>{{issue.error}}</td><td>{{issue.suggestion}}</td></tr></tbody></table></div>
        <h3>Products checked</h3><div class="table-wrap"><table><thead><tr><th>Product row</th><th>Product</th><th>Category</th><th>Brand</th><th>Unit</th><th>Warranty</th><th>Condition</th><th>Shipping weight (kg)</th><th>Mark as New</th><th>Variants</th><th>Check</th></tr></thead><tbody><tr v-for="row in preview.rows" :key="row.rowNumber"><td>{{row.rowNumber}}</td><td>{{row.name||'Unnamed product'}}</td><td>{{row.category||'—'}}</td><td>{{row.brand||'—'}}</td><td>{{row.unitOfMeasure||'—'}}</td><td>{{row.warranty||'No warranty'}}</td><td>{{row.condition||'—'}}</td><td>{{row.shippingWeight??'—'}}</td><td>{{row.isNew?'Yes':'No'}}</td><td><ul><li v-for="variant in row.variants" :key="variant.name">{{variant.name}} · {{variant.sellingPrice===null?'No selling price':`LKR ${variant.sellingPrice}`}} · {{variant.stock===null?'No opening stock':`Stock ${variant.stock}`}} · Reorder {{variant.reorderQuantity}} · Location {{variant.stockLocation||'—'}}{{variant.quickbooksItemCode?` · QB ${variant.quickbooksItemCode}`:''}}</li></ul></td><td><strong :class="row.status==='Valid'?'valid':'invalid'">{{row.status==='Valid'?'Ready':'Needs attention'}}</strong></td></tr></tbody></table></div>
      </div></section>
      <section class="card"><div class="section-number">4</div><div class="section-body confirm-card"><div><h2>Confirm and import</h2><p v-if="hasBlockingErrors">Correct all issues and upload the workbook again before importing.</p><p v-else>Everything looks good. Confirm to add the products, variants, prices, and opening stock. Add variant specifications afterward in product administration.</p></div><button class="primary-button" :disabled="busy||preview.counts.valid===0||hasBlockingErrors" @click="confirmImport">{{busy&&stage==='importing'?'Importing…':`Confirm ${preview.counts.products} products`}}</button></div></section>
    </template>
    <section v-if="result" class="card results"><div class="section-body"><h2>Import results</h2><p>{{result.imported}} products added · {{result.failed}} failed</p><button v-if="result.results?.some(row=>row.status==='Failed')" class="secondary-button" :disabled="busy" @click="retryFailed">Retry failed products</button><h3>Added successfully ({{addedProducts.length}})</h3><ul><li v-for="row in addedProducts" :key="row.rowNumber">{{row.name}} — item code {{row.itemCode}}</li></ul><h3 v-if="failedProducts.length">Could not add ({{failedProducts.length}})</h3><div v-if="failedProducts.length" class="table-wrap"><table><thead><tr><th>Product row</th><th>Product</th><th>What happened</th></tr></thead><tbody><tr v-for="row in failedProducts" :key="row.rowNumber"><td>{{row.rowNumber}}</td><td>{{row.name}}</td><td>{{row.error||row.errors?.join(' ')||'Please review this product.'}}</td></tr></tbody></table></div></div></section>
  </main>
</template>

<style scoped>
.import-page{max-width:1250px}.steps{display:flex;gap:10px;flex-wrap:wrap;margin:0 0 20px;padding-left:25px;color:#687385}.steps li{padding:8px 12px;background:#f4f6f8;border-radius:8px}.steps .current{color:#174ea6;background:#e7f0ff;font-weight:700}.card{display:flex;gap:16px;background:#fff;border:1px solid #e2e6ec;border-radius:12px;padding:22px;margin-bottom:18px}.card h2{font-size:18px;margin:0 0 8px}.card p{color:#697386;margin:0 0 16px}.section-number{width:32px;height:32px;flex:0 0 32px;border-radius:50%;background:#e7f0ff;color:#174ea6;display:grid;place-items:center;font-weight:700}.section-body{flex:1;min-width:0}.notice{padding:12px 16px;background:#eef5ff;border-radius:8px;margin-bottom:16px}.upload-row,.card-heading,.confirm-card{display:flex;align-items:center;justify-content:space-between;gap:16px}.upload-row{justify-content:flex-start;flex-wrap:wrap}.secondary-button{background:white;border:1px solid #cbd2dc;border-radius:7px;padding:9px 14px;cursor:pointer}.stats{display:grid;grid-template-columns:repeat(4,minmax(100px,1fr));gap:12px;margin:16px 0}.stats div{background:#f7f8fa;padding:14px;border-radius:8px;display:flex;flex-direction:column}.stats b{font-size:22px}.stats span{font-size:13px;color:#697386}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:14px}th,td{text-align:left;padding:10px;border-bottom:1px solid #e7eaf0;vertical-align:top}th{background:#f8f9fb;white-space:nowrap}td ul,.workbook-errors ul{margin:6px 0 0;padding-left:18px;color:#a32626}.plain-list{line-height:1.8;padding-left:20px}.valid{color:#168044}.invalid{color:#b42318}progress{width:100%;margin-top:14px}.confirm-card p{margin-bottom:0}.results{overflow:hidden}@media(max-width:800px){.stats{grid-template-columns:repeat(2,minmax(120px,1fr))}.card-heading,.confirm-card{align-items:flex-start;flex-direction:column}}
</style>
